const W = H.W, Ht = H.H;
const Pw = 0.5;
const I0 = 1e-12;
const r = Math.max(0.5, P.r);
const I = Pw / (4 * Math.PI * r * r);
const beta = 10 * Math.log10(I / I0);
const sx = 150, sy = Ht * 0.55;
const pulse = (t % 1.2) / 1.2;
const rpx = 30 + pulse * 230;
const circ = [];
for (let a = 0; a <= 48; a++) {
  const th = 2 * Math.PI * a / 48;
  circ.push([sx + rpx * Math.cos(th), sy + rpx * Math.sin(th)]);
}
H.path(circ, { color: H.colors.grid, width: 2 });
H.circle(sx, sy, 9, { fill: H.colors.warn });
const lx = sx + Math.min(300, 18 * r);
H.circle(lx, sy, 7, { fill: H.colors.good });
H.line(sx, sy, lx, sy, { color: H.colors.sub, width: 1, dash: [4, 4] });
H.text("r = " + r.toFixed(1) + " m", (sx + lx) / 2 - 24, sy - 14, { color: H.colors.sub, size: 12 });
